 startMenu.innerHTML='<div class="start-content"><img class="start-logo" src="assets/hackenia-logo-v112.svg" width="118" height="118" alt="Dé de Hackenia dans sa bulle"><h1 id="start-title">Dice of Hackenia</h1><p class="start-subtitle">Trading Dice Game</p><div class="start-choices"><button type="button" class="start-choice" data-start="new">'+startGlyph('new')+'<span><strong>Nouvelle partie</strong><small>50 Bubulles pour commencer votre aventure</small></span></button><button type="button" class="start-choice" data-start="load">'+startGlyph('load')+'<span><strong>Charger partie</strong><small>Reprendre votre progression</small></span></button><button type="button" class="start-choice" data-start="learn">'+startGlyph('learn')+'<span><strong>Apprendre à jouer</strong><small>Découvrir les règles et vos premiers pas</small></span></button></div><p class="start-footnote">Votre aventure est sauvegardée sur cet appareil.</p></div>';startMenu.hidden=false;document.body.classList.add('start-menu-open');updateStartChoices();window.scrollTo({top:0,left:0,behavior:'instant'});
