function play(){
 const available=profile.decks.filter(d=>legal(d.dice)),preferred=available.find(d=>d.id===profile.preferredDeckId)||available[0];
 const terrainList=[['terre','🌲','Clairière des murmures'],['feu','🌋','Les Lèvres du Brasier'],['glace','❄️','Glacier éternel'],['vent','☁️','Plateau des vents'],['eau','🌊','Lagon cristallin'],['foudre','⚡','Plaine foudroyée']];
 const terrainDetails={
  terre:{text:'Une clairière boisée traversée par une rivière.',effect:'Les dés de terre gagnent +1 en attaque.'},
  feu:{text:'Un cratère incandescent, parcouru de fissures de lave.',effect:'Les dés de feu gagnent +1. Six évents bloquent les déplacements.'},
  glace:{text:'Forêt enneigée, bonhomme de neige, stalagmites et plaque de glace.',effect:'Les dés de glace gagnent +1. Les créatures glissent jusqu’au bout des dalles libres ; un adversaire arrête leur course et déclenche un combat.'},
  vent:{text:'Un plateau d’altitude balayé par les courants.',effect:'Les dés de vent gagnent +1 en attaque.'},
  eau:{text:'Un rivage tropical bordé d’eaux profondes.',effect:'Les dés d’eau gagnent +1 en attaque.'},
  foudre:{text:'Une plaine sombre où les éclairs déchirent le ciel.',effect:'Les dés de foudre gagnent +1 en attaque.'}
 };
 const deckOptions=available.map(d=>'<option value="'+esc(d.id)+'"'+(preferred?.id===d.id?' selected':'')+'>'+esc(d.name)+' · 10 dés'+(d.dice.includes(36)?' · Eberien ❄️':'')+'</option>').join('');
 const terrainOptions=terrainList.map(([id,em,name])=>'<option value="'+id+'">'+em+' '+name+'</option>').join('');
 $('portal-content').innerHTML='<div class="portal-title"><div><h2>Jouer</h2></div><span class="portal-muted">Duel contre l’IA</span></div><p>Choisissez votre deck et le terrain ; son aperçu montre le plateau réel avant le lancement.</p><p class="portal-muted">Victoire : 30 Bubulles · Défaite : 5 Bubulles.</p><div class="deck-layout"><div class="play-controls"><label for="play-deck">Votre deck</label><select id="play-deck" style="width:100%;padding:12px;margin:8px 0 16px">'+(available.length?'':'<option value="">Aucun deck jouable</option>')+deckOptions+'</select><label for="play-terrain">Terrain</label><select id="play-terrain" style="width:100%;padding:12px;margin:8px 0 16px">'+terrainOptions+'</select><div class="deck-actions"><button class="portal-primary" data-action="start-play" '+(preferred?'':'disabled')+'>Lancer le duel ↗</button><button data-action="decks">Composer un deck</button></div>'+(available.length?'':'<p class="portal-muted">Aucun deck sauvegardé valide. Créez et sauvegardez un deck de 10 dés dans « Mes decks ».</p>')+'</div><section class="terrain-preview" id="play-terrain-preview" data-terrain="terre" aria-live="polite"><div class="terrain-preview-art" id="play-terrain-art" aria-label="Aperçu réel du plateau de jeu"></div><div class="terrain-preview-copy"><span class="terrain-preview-kicker">Aperçu du terrain</span><strong id="terrain-preview-title">Clairière des murmures</strong><span id="terrain-preview-text">Une clairière boisée traversée par une rivière.</span><small id="terrain-preview-effect">Les dés de terre gagnent +1 en attaque.</small></div></section></div>';
 const sel=$('play-deck'),start=$('portal-content').querySelector('[data-action="start-play"]'),terrain=$('play-terrain');
 function updateTerrainPreview(){const id=terrain.value,d=terrainDetails[id]||terrainDetails.terre,meta=terrainList.find(item=>item[0]===id),art=$('play-terrain-art');$('play-terrain-preview').dataset.terrain=id;$('terrain-preview-title').textContent=meta?.[2]||d.text;$('terrain-preview-text').textContent=d.text;$('terrain-preview-effect').textContent=d.effect;art.setAttribute('aria-label','Plateau réel : '+(meta?.[2]||d.text));window.HackeniaView?.preview?.(id,art)}
 terrain.addEventListener('change',updateTerrainPreview);updateTerrainPreview();
 sel.addEventListener('change',()=>{start.disabled=!available.some(d=>d.id===sel.value);if(!start.disabled&&profile.preferredDeckId!==sel.value){const next=structuredClone(profile);next.preferredDeckId=sel.value;commit(next)}})
}
function quick(){$('portal-content').innerHTML=`<div class="portal-title"><div><h2>Partie rapide</h2></div><span class="portal-muted">10 dés par équipe · Adversaire IA</span></div><p>Dés aléatoires, terrain aléatoire et adversaire IA.</p><p class="portal-muted">Victoire : 30 Bubulles · Défaite : 5 Bubulles.</p><div class="deck-actions"><button class="portal-primary" data-action="start-quick">Lancer une partie aléatoire ↗</button>${game.hasMatch()?'<button data-action="resume">Reprendre la partie en cours</button>':''}</div>`}
function characterArt(i){return game.portrait(i)}
function card(i,action='detail'){const d=defs[i],n=profile.inventory[i]||0,available=n-(counts(draft.dice)[i]||0),label=action==='add'?`Ajouter (${Math.max(0,available)} disponible${available>1?'s':''})`:'Examiner le dé';return `<article class="collect-card ${!n?'locked':''}" style="--ec:${colors[d.el]};--rim:${rims[rarity(d)-1]}"><span class="owned-count">${n?'× '+n:'Non possédé'}</span><div class="collect-art" aria-hidden="true">${characterArt(i)}</div><div class="card-kind">${E[d.el]} · Niveau ${d.lv}</div><h3>${esc(d.cn)}</h3><div class="card-rarity">${rare[rarity(d)-1]}</div><div class="card-stats">${d.c.length} dalles · Invocation ${d.need}+<br>${d.nd} dé${d.nd>1?'s':''} de lancer</div><button data-action="${action}" data-id="${i}" ${action==='add'&&(available<=0||draft.dice.length>=10)?'disabled':''}>${label}</button></article>`}
function tools(){return `<div class="portal-tools"><label class="search">Rechercher<input id="collection-search" type="search" value="${esc(filter.q)}" placeholder="Nom, élément…"></label><label>Élément<select id="filter-element"><option value="">Tous les éléments</option>${Object.entries(E).map(([k,v])=>`<option value="${k}" ${filter.el===k?'selected':''}>${v}</option>`).join('')}</select></label><label>Rareté<select id="filter-level"><option value="">Toutes les raretés</option>${rare.map((r,i)=>`<option value="${i+1}" ${filter.lv===String(i+1)?'selected':''}>${r}</option>`).join('')}</select></label><label>Trier par<select id="filter-sort">${[['name','Nom A → Z'],['level-desc','Niveau décroissant'],['level-asc','Niveau croissant'],['element','Élément'],['quantity','Quantité possédée']].map(([v,n])=>`<option value="${v}" ${filter.sort===v?'selected':''}>${n}</option>`).join('')}</select></label>${view==='collection'?`<label class="check"><input id="filter-owned" type="checkbox" ${filter.owned?'checked':''}>Possédés uniquement</label>`:''}<button data-action="reset-filters">Réinitialiser</button></div>`}
const norm=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
function visible(){return defs.map((d,i)=>({d,i})).filter(({d,i})=>(!(view==='decks'||filter.owned)||profile.inventory[i]>0)&&(!filter.el||d.el===filter.el)&&(!filter.lv||rarity(d)===+filter.lv)&&norm(d.cn+' '+E[d.el]+' '+rare[rarity(d)-1]).includes(norm(filter.q))).sort((a,b)=>{let c=filter.sort==='level-desc'?b.d.lv-a.d.lv:filter.sort==='level-asc'?a.d.lv-b.d.lv:filter.sort==='element'?E[a.d.el].localeCompare(E[b.d.el],'fr'):filter.sort==='quantity'?(profile.inventory[b.i]||0)-(profile.inventory[a.i]||0):0;return c||a.d.cn.localeCompare(b.d.cn,'fr')||a.d.lv-b.d.lv}).map(x=>x.i)}
function grid(){const ids=visible();$('collection-count').textContent=ids.length+' dé'+(ids.length>1?'s':'')+' affiché'+(ids.length>1?'s':'');$('collection-grid').innerHTML=ids.length?ids.map(i=>card(i,view==='decks'?'add':'detail')).join(''):'<div id="portal-empty">Aucun dé ne correspond à ces filtres.</div>'}
function bindTools(){[['collection-search','q','input'],['filter-element','el','change'],['filter-level','lv','change'],['filter-sort','sort','change'],['filter-owned','owned','change']].forEach(([name,k,event])=>{const el=$(name);if(el)el.addEventListener(event,()=>{filter[k]=el.type==='checkbox'?el.checked:el.value;grid()})})}
function collection(){const owned=Object.values(profile.inventory).reduce((a,b)=>a+b,0),unique=Object.values(profile.inventory).filter(n=>n>0).length;$('portal-content').innerHTML=`<div class="portal-title"><div><h2>Ma collection</h2></div><span class="portal-muted">${unique} / ${defs.length} dés différents · ${owned} exemplaires</span></div>${tools()}<p class="portal-muted" id="collection-count"></p><div class="portal-grid" id="collection-grid"></div>`;grid();bindTools()}
function legal(d){const c=counts(d);return d.length===10&&d.every(validId)&&Object.entries(c).every(([i,n])=>n<=(profile.inventory[i]||0))}
function deckTray(){return `<aside class="deck-tray" aria-label="Deck en cours de modification"><div class="deck-tray-head"><strong>Deck en cours <span>${draft.dice.length}/10</span></strong><button data-action="save-deck" ${!storageOK||!draft.name.trim()||!legal(draft.dice)?'disabled':''}>Sauvegarder</button></div><div class="deck-tray-slots">${Array.from({length:10},(_,k)=>{const d=defs[draft.dice[k]];return `<div class="deck-tray-slot ${d?'filled':''}" style="--slot-color:${d?colors[d.el]:'#52616a'}">${d?`<button class="deck-tray-detail" data-action="detail" data-id="${draft.dice[k]}" title="${esc(d.cn)} · Niveau ${d.lv}" aria-label="Examiner ${esc(d.cn)} dans le deck"><span>${characterArt(draft.dice[k])}</span><b>${esc(d.cn)}</b><small>Niv. ${d.lv}</small></button><button class="deck-tray-remove" data-action="remove" data-id="${k}" aria-label="Retirer ${esc(d.cn)} du deck en cours">×</button>`:`<span class="deck-tray-empty">${k+1}</span>`}</div>`}).join('')}</div></aside>`}
function decks(preserveScroll=false){const position=window.scrollY;$('portal-content').innerHTML=`<div class="portal-title"><div><h2>Mes decks</h2></div><button data-action="new-deck">＋ Nouveau deck</button></div><div class="deck-layout"><aside><p class="portal-muted">Decks sauvegardés</p><div class="deck-saved">${profile.decks.map(d=>`<button data-action="load-deck" data-key="${esc(d.id)}" aria-pressed="${draft.id===d.id}">${esc(d.name)}<small style="display:block;color:#aebd9d">${d.dice.length} / 10 dés${legal(d.dice)?' · Prêt':''}</small></button>`).join('')||'<p>Aucun deck sauvegardé.</p>'}</div></aside><div><div class="deck-editor-header"><input class="deck-name" id="deck-name" maxlength="40" value="${esc(draft.name)}" aria-label="Nom du deck"><strong>${draft.dice.length} / 10 dés</strong></div><div class="deck-slots">${Array.from({length:10},(_,k)=>{const d=defs[draft.dice[k]];return `<div class="deck-slot">${d?`<b>${characterArt(draft.dice[k])}</b>${esc(d.cn)}<br>Niv. ${d.lv}<br><button data-action="remove" data-id="${k}" aria-label="Retirer ${esc(d.cn)} du deck">Retirer</button>`:`<b style="opacity:.2">◇</b>Emplacement ${k+1}`}</div>`}).join('')}</div><div class="deck-balance">${Object.keys(E).map(el=>`${E[el]} : ${draft.dice.filter(i=>defs[i].el===el).length}`).join(' · ')}</div><p class="portal-muted">10 dés possédés. Chaque exemplaire peut être utilisé une fois dans ce deck ; vos autres decks peuvent le réutiliser.</p><div class="deck-actions"><button class="portal-primary" data-action="save-deck" ${!storageOK||!draft.name.trim()||!legal(draft.dice)?'disabled':''}>Sauvegarder</button><button data-action="play-deck" ${!legal(draft.dice)?'disabled':''}>Jouer ce deck contre l’IA</button><button data-action="clear-deck">Vider</button>${draft.id?'<button data-action="delete-deck">Supprimer ce deck</button>':''}</div></div></div><h3 style="font:23px Georgia;margin-top:35px">Ajouter des dés à votre équipe</h3>${tools()}<p class="portal-muted" id="collection-count"></p><div class="portal-grid" id="collection-grid"></div>${deckTray()}`;grid();bindTools();if(preserveScroll)requestAnimationFrame(()=>window.scrollTo({top:position,behavior:"instant"}));$('deck-name').oninput=e=>{draft.name=e.target.value;saveDraft();$('portal-content').querySelectorAll('[data-action="save-deck"]').forEach(b=>b.disabled=!storageOK||!draft.name.trim()||!legal(draft.dice))}}
function pendingPouches(){return profile.pouchQueue?.length||0}
function openNextPouch(){if(shopBusy||!pendingPouches())return;const next=structuredClone(profile),pack=next.pouchQueue.shift();if(commit(next)){latest=pack.dice;latestFirstSeen=pack.firstSeen;shopBusy=true;shop(true)}}
function purchasePouches(count){if(shopBusy||!storageOK)return;const next=window.HackeniaPurchases.plan(profile,count);if(next&&commit(next))openNextPouch()}
function shop(opening=false){const preservedScrollY=window.scrollY;placeWallet(false);window.HackeniaPouch?.dispose($('pouch-theatre'));
 const remaining=pendingPouches(),canOpen=remaining>0||profile.gold>=10;const dice=latest.map(i=>{const d=defs[i];return{id:i,name:d.cn,rarity:rare[rarity(d)-1],color:colors[d.el],metal:rims[rarity(d)-1],element:d.el,elementName:E[d.el],elementSymbol:({eau:"◈",glace:"❄",feu:"✹",terre:"❧",vent:"〰",foudre:"ϟ"})[d.el]||"✧",faces:d.c.map(a=>a[2])}});
 $('portal-content').innerHTML=`<div class="shop-actions deck-actions"><button class="portal-primary" data-action="buy" ${shopBusy||!storageOK||!canOpen?'disabled':''}>${shopBusy?'Ouverture en cours…':remaining?'Ouvrir la bourse suivante':'Délier la bourse · '+currency(10)}</button><button class="buy-ten" data-action="buy-ten" ${shopBusy||!storageOK||profile.gold<90||remaining?'disabled':''}>10 bourses · 90 Bubulles</button><button data-action="options">Personnaliser</button></div>${window.HackeniaPouch.markup(dice,opening)}<div class="shop-followup">${latest.length?'<button data-action="collection">Retrouver ces dés dans ma collection</button>':''}</div><details class="portal-muted"><summary>Probabilités par dé</summary><p>Commun 35 % · Peu commun 25 % · Rare 18 % · Épique 12 % · Légendaire 8 % · Divin 2 %. Les six éléments sont équiprobables.</p></details>`;
 placeWallet(true);requestAnimationFrame(()=>window.scrollTo({top:preservedScrollY,left:0,behavior:'instant'}));
 const stage=$('pouch-theatre');
 const updateBag=()=>{if(!stage.isConnected)return;stage.scrollTop=0;stage.parentElement.scrollTop=0;const enabled=!shopBusy&&storageOK&&(pendingPouches()>0||profile.gold>=10);const hint=stage.nextElementSibling;if(hint?.classList.contains('pouch-open-hint'))hint.textContent=shopBusy?'Ouverture en cours…':pendingPouches()?'Touchez ou faites glisser la bourse pour ouvrir la suivante':'Touchez ou faites glisser la bourse pour ouvrir';stage.classList.toggle('pouch-can-buy',enabled);const bag=stage.querySelector('.pouch-prop-back');if(bag){bag.setAttribute('aria-disabled',String(!enabled));bag.setAttribute('aria-label',enabled?(pendingPouches()?'Ouvrir la prochaine bourse déjà achetée':'Ouvrir une bourse'):shopBusy?'Ouverture en cours':'Bubulles insuffisantes');bag.tabIndex=enabled?0:-1}};
 const bag=stage.querySelector('.pouch-prop-back');if(bag){bag.setAttribute('role','button');const openBag=()=>{if(stage.isConnected&&!shopBusy&&storageOK&&(pendingPouches()>0||profile.gold>=10))$('portal-content').querySelector('[data-action="buy"]')?.click()};let origin=null;bag.addEventListener('pointerdown',e=>{origin={x:e.clientX,y:e.clientY};bag.setPointerCapture?.(e.pointerId)});bag.addEventListener('pointerup',e=>{if(origin&&Math.hypot(e.clientX-origin.x,e.clientY-origin.y)>24)openBag();origin=null});bag.addEventListener('pointercancel',()=>origin=null);bag.addEventListener('click',openBag);bag.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openBag()}})}updateBag();
 const openingGuard=opening?setTimeout(()=>{const activeStage=$('pouch-theatre');if(activeStage?.classList.contains('pouch-pending')){try{window.HackeniaPouch.reveal(activeStage)}catch{}shopBusy=false;const buy=$('portal-content').querySelector('[data-action="buy"]');if(buy){buy.disabled=!storageOK||!(pendingPouches()>0||profile.gold>=10);buy.innerHTML=pendingPouches()?'Ouvrir la bourse suivante':'Délier la bourse · '+currency(10)}const ten=$('portal-content').querySelector('[data-action="buy-ten"]');if(ten)ten.disabled=!storageOK||profile.gold<90||pendingPouches()>0;updateBag()}},5000):null;
 window.HackeniaPouch.start(stage,opening,{firstSeen:opening?latestFirstSeen:[],modelInfo:i=>game.modelInfo(i),loadModelViewer:()=>game.loadModelViewer()}).catch(()=>{if(stage.isConnected){try{window.HackeniaPouch.reveal(stage)}catch{}}}).finally(()=>{if(opening){clearTimeout(openingGuard);const activeStage=$('pouch-theatre');if(activeStage?.classList.contains('pouch-pending')){try{window.HackeniaPouch.reveal(activeStage)}catch{}}shopBusy=false;if(view==='shop'){const buy=$('portal-content').querySelector('[data-action="buy"]');if(buy){buy.disabled=!storageOK||!(pendingPouches()>0||profile.gold>=10);buy.innerHTML=pendingPouches()?'Ouvrir la bourse suivante':'Délier la bourse · '+currency(10)}const ten=$('portal-content').querySelector('[data-action="buy-ten"]');if(ten)ten.disabled=!storageOK||profile.gold<90||pendingPouches()>0;}updateBag()}});
}
function freshStart(){
 const modal=document.createElement('dialog');modal.id='new-adventure-dialog';modal.setAttribute('aria-labelledby','new-adventure-title');modal.innerHTML='<h2 id="new-adventure-title">Une nouvelle aventure</h2><p>La collection, les decks, les Bubulles et les options de cet appareil retrouveront leur état de première connexion. L’introduction se jouera à nouveau.</p><p>Une copie de votre progression actuelle permettra de la restaurer depuis les options.</p><div class="dialog-actions"><button type="button" data-cancel autofocus>Garder ma progression</button><button type="button" data-confirm>Recommencer à zéro</button></div>';document.body.append(modal);modal.addEventListener('close',()=>modal.remove());modal.querySelector('[data-cancel]').onclick=()=>modal.close();modal.querySelector('[data-confirm]').onclick=()=>{const confirm=modal.querySelector('[data-confirm]');if(confirm.disabled)return;confirm.disabled=true;if(!window.HackeniaProfileTools.reset(localStorage,starter())){confirm.disabled=false;toast('Le nouveau départ n’a pas pu être enregistré. Votre progression est conservée.');return}location.hash='accueil';location.reload()};modal.showModal();
}
function restoreBeforeReset(){const values=window.HackeniaProfileTools.backup(localStorage);try{validate(JSON.parse(values?.[KEY]));if(!window.HackeniaProfileTools.restore(localStorage))throw Error();location.reload()}catch{toast('La progression précédente n’a pas pu être restaurée.')}}
function options(){const s=window.HackeniaSettings.get(),choice=(value,label,current)=>`<option value="${value}" ${value===current?'selected':''}>${label}</option>`;
 $('portal-content').innerHTML=`<div class="portal-title"><div><h2>Options</h2></div><span class="portal-muted">Options sauvegardées automatiquement</span></div><div class="options-layout"><div class="options-preview"><div class="settings-bag-preview">${window.HackeniaSettings.pouchMarkup()}</div><p>Aperçu de la bourse</p></div><form id="options-form"><fieldset><legend>Votre bourse de dés</legend><div class="options-fields"><label>Couleur du cuir<select name="pouchColor">${[['brun','Cuir brun'],['bordeaux','Bordeaux'],['bleu','Bleu nuit'],['vert','Vert forêt'],['noir','Cuir noir']].map(([v,l])=>choice(v,l,s.pouchColor)).join('')}</select></label><label>Texture<select name="texture">${[['grain','Cuir grainé'],['suede','Daim velouté'],['ecailles','Cuir embossé en écailles']].map(([v,l])=>choice(v,l,s.texture)).join('')}</select></label><label>Cordelette<select name="cord">${[['or','Dorée'],['argent','Argentée'],['cuivre','Cuivrée']].map(([v,l])=>choice(v,l,s.cord)).join('')}</select></label></div></fieldset><fieldset><legend>Son</legend><label class="options-check"><input type="checkbox" name="music" ${s.music?'checked':''}>Musique de duel (Triade d’Hackénia)</label><label>Volume musique <output id="music-volume-output">${Math.round(s.musicVolume*100)} %</output><input type="range" name="musicVolume" min="0" max="100" value="${Math.round(s.musicVolume*100)}"></label><label class="options-check"><input type="checkbox" name="sound" ${s.sound?'checked':''}>Activer les effets sonores</label><label>Volume des effets <output id="volume-output">${Math.round(s.volume*100)} %</output><input type="range" name="volume" min="0" max="100" value="${Math.round(s.volume*100)}"></label><button type="button" data-action="test-sound">Écouter un son</button></fieldset><fieldset><legend>Affichage</legend><label class="options-check"><input type="checkbox" name="motion" ${s.motion?'checked':''}>Activer les animations et les effets d’ambiance</label><p class="portal-muted">Le plateau détaillé est activé automatiquement. La préférence de réduction des animations de votre appareil reste respectée.</p></fieldset><button type="button" data-action="shop" class="portal-primary">Ouvrir la boutique</button></form></div><section class="first-visit-options"><h3>Votre aventure</h3><p>Retrouvez l’introduction du jeu ou recommencez avec la collection, le deck et les 50 Bubulles de départ.</p><div class="deck-actions"><button type="button" data-action="replay-intro">Revoir l’introduction</button><button type="button" data-action="start-menu">Menu de démarrage</button><button type="button" data-action="fresh-start">Recommencer à zéro</button>${window.HackeniaProfileTools.backup(localStorage)?.[KEY]?'<button type="button" data-action="restore-before-reset">Restaurer ma progression précédente</button>':''}</div></section>`;
 $('options-form').addEventListener('submit',e=>e.preventDefault());$('options-form').addEventListener('input',e=>{const el=e.target;if(!el.name)return;const value=el.type==='checkbox'?el.checked:['volume','musicVolume'].includes(el.name)?Number(el.value)/100:el.value;
 if(!window.HackeniaSettings.set({[el.name]:value})){toast('Ces options n’ont pas pu être sauvegardées.');return}if(el.name==='volume')$('volume-output').textContent=el.value+' %';if(el.name==='musicVolume')$('music-volume-output').textContent=el.value+' %';if(['pouchColor','texture','cord'].includes(el.name))document.querySelector('.settings-bag-preview').innerHTML=window.HackeniaSettings.pouchMarkup();});
}
const detailSymbols={feu:'<path d="M13 2c2 6-3 6 0 10 2-1 3-3 3-5 6 6 6 14-4 15C2 21 2 13 7 9c0 3 1 4 2 4-2-5 4-7 4-11Z"/>',glace:'<path d="M12 2v20M3.3 7l17.4 10M3.3 17 20.7 7M8 4l4 3 4-3M8 20l4-3 4 3M3 11l4-2V5M21 13l-4 2v4M3 13l4 2v4M21 11l-4-2V5"/>',eau:'<path d="M12 2S4 11 4 15a8 8 0 0 0 16 0c0-4-8-13-8-13ZM8 15c0 3 2 4 4 4"/>',terre:'<path d="m2 20 7-15 4 8 3-5 6 12ZM6 12l3 2 3-3M14 13l3 2 2-1"/>',vent:'<path d="M3 8h12c5 0 5-6 1-6-2 0-3 1-3 3M2 12h17c4 0 4 6 0 6M4 16h7c5 0 5 6 1 6"/>',foudre:'<path d="m14 2-11 12h8l-1 8 11-13h-8Z"/>'};
function detailElement(el){return `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${detailSymbols[el]||''}</svg>`}
function detailNet(d){const xs=d.c.map(c=>c[0]),ys=d.c.map(c=>c[1]),minX=Math.min(...xs),minY=Math.min(...ys),cols=Math.max(...xs)-minX+1,rows=Math.max(...ys)-minY+1;return `<div class="detail-net" role="img" aria-label="Forme du dé déployé, ${d.c.length} dalles. Valeurs : ${d.c.map(c=>c[2]).join(', ')}" style="--net-cols:${cols};--net-rows:${rows}">${d.c.map(([x,y,v])=>`<span class="detail-tile" style="grid-column:${x-minX+1};grid-row:${y-minY+1}">${v}</span>`).join('')}</div>`}
let detailToken=0;
dialog.addEventListener('close',()=>{detailToken++;dialog.replaceChildren()});
dialog.addEventListener('click',e=>{if(e.target!==dialog)return;const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()});
function detail(i){
 const d=defs[i];if(!d)return;const token=++detailToken,n=profile.inventory[i]||0;
 dialog.style.setProperty('--detail-color',colors[d.el]);dialog.style.setProperty('--detail-metal',rims[rarity(d)-1]);dialog.setAttribute('aria-labelledby','detail-name');dialog.removeAttribute('aria-label');
 dialog.innerHTML=`<button class="detail-close" type="button" data-close aria-label="Fermer la fiche" autofocus><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18"/></svg></button><article class="character-sheet"><div class="detail-showcase"><div class="detail-showcase-top"><span class="detail-element">${detailElement(d.el)}${E[d.el]}</span><span class="detail-level">Niveau <b>${d.lv}</b></span></div><div class="detail-portrait"><button type="button" class="character-enlarge" data-inspect aria-label="Agrandir le personnage"><svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5M3 3l6 6m12-6-6 6M3 21l6-6m12 6-6-6"/></svg></button><div class="detail-orbit" aria-hidden="true"></div><div class="detail-character" aria-hidden="true">${characterArt(i)}</div><div id="collection-model"></div><span class="detail-pedestal" aria-hidden="true"></span></div><div class="detail-showcase-bottom"><span class="detail-rarity"><i aria-hidden="true"></i>${rare[rarity(d)-1]}</span><p class="detail-model-hint" hidden>Faites glisser pour tourner</p></div></div><div class="detail-information"><header><h2 id="detail-name">${esc(d.cn)}</h2><p class="detail-description">${esc(d.lo)}</p></header><dl class="detail-stats"><div><dt>Invocation</dt><dd>${d.need}<span>+</span></dd></div><div><dt>Dés de lancer</dt><dd>${d.nd}</dd></div><div><dt>Collection</dt><dd>${n}<span>ex.</span></dd></div></dl><section class="detail-deployment" aria-labelledby="detail-net-title"><div class="detail-deployment-head"><h3 id="detail-net-title">Déploiement</h3><span>${d.c.length} dalles</span></div><div class="detail-deployment-body">${detailNet(d)}<p>Chaque chiffre indique la valeur de sa dalle.</p></div></section><div class="detail-combat-note"><span aria-hidden="true">⚔</span><p><strong>Puissance en combat</strong>Valeur de la dalle occupée + bonus élémentaires.</p></div><footer class="detail-footer"><span>${n?`${n} exemplaire${n>1?'s':''} dans votre collection`:'Pas encore dans votre collection'}</span><button type="button" data-close>Fermer la fiche</button></footer></div></article>`;
 dialog.querySelector('[data-inspect]').onclick=()=>window.HackeniaInspector.open({index:i,name:d.cn});dialog.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>dialog.close());if(!dialog.open)dialog.showModal();dialog.scrollTop=0;
 game.modelInfo(i).then(async info=>{if(token!==detailToken||!info?.glb||!dialog.open)return;const src='assets/'+info.glb;const r=await fetch(src,{method:'HEAD'});if(token!==detailToken||!r.ok||!dialog.open)return;game.loadModelViewer();const host=dialog.querySelector('#collection-model'),portrait=dialog.querySelector('.detail-character'),hint=dialog.querySelector('.detail-model-hint');const mv=document.createElement('model-viewer');mv.setAttribute('src',src);mv.setAttribute('camera-controls','');if(window.HackeniaSettings.get().motion)mv.setAttribute('autoplay','');if(window.HackeniaSettings.get().motion&&!matchMedia('(prefers-reduced-motion: reduce)').matches)mv.setAttribute('auto-rotate','');mv.setAttribute('shadow-intensity','1');mv.setAttribute('interaction-prompt','none');mv.setAttribute('alt',`Modèle 3D de ${d.cn}`);mv.addEventListener('load',()=>{if(token!==detailToken||!dialog.open)return;portrait.hidden=true;host.classList.add('is-ready');hint.hidden=false});host.append(mv)}).catch(()=>{})
}
$('portal-content').addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,i=+b.dataset.id;if(a==='start-menu'){showStartMenu();return}else if(a==='replay-intro'){window.HackeniaIntro?.play();return}else if(a==='fresh-start'){freshStart();return}else if(a==='restore-before-reset'){restoreBeforeReset();return}else if(a==='start-quick')launch();else if(a==='start-play'){const deck=profile.decks.find(d=>d.id===$('play-deck')?.value);if(deck&&legal(deck.dice))launch(deck.dice,$('play-terrain')?.value)}else if(a==='resume'){window.HackeniaView?.clearPreview?.();document.body.classList.remove('portal-open');location.hash='partie';game.resume();window.dispatchEvent(new Event('resize'))}else if(['quick','collection','decks','play','options','shop'].includes(a))navigate(a,true);else if(a==='test-sound'){if(window.HackeniaSettings.get().sound)window.HackeniaSettings.play('test');else toast('Activez les effets sonores pour écouter le son.')}else if(a==='detail')detail(i);else if(a==='reset-filters'){filter={q:'',el:'',lv:'',owned:true,sort:'name'};render()}else if(a==='new-deck'){draft={id:null,name:'Nouveau deck',dice:[]};saveDraft();decks()}else if(a==='load-deck'){const d=profile.decks.find(d=>d.id===b.dataset.key);if(d){draft=JSON.parse(JSON.stringify(d));saveDraft();decks()}}else if(a==='add'){const used=counts(draft.dice)[i]||0;if(draft.dice.length<10&&used<(profile.inventory[i]||0)){draft.dice.push(i);saveDraft();decks(true)}}else if(a==='remove'){draft.dice.splice(i,1);saveDraft();decks(true)}else if(a==='clear-deck'){draft.dice=[];saveDraft();decks()}else if(a==='save-deck'){if(!legal(draft.dice)||!draft.name.trim())return;const next=structuredClone(profile),d={id:draft.id||id(),name:draft.name.trim().slice(0,40),dice:[...draft.dice]},k=next.decks.findIndex(x=>x.id===d.id);if(k>=0)next.decks[k]=d;else next.decks.push(d);if(commit(next)){draft=d;saveDraft();decks();toast('Deck sauvegardé.')}}else if(a==='delete-deck'){const next=structuredClone(profile);next.decks=next.decks.filter(d=>d.id!==draft.id);if(commit(next)){draft={id:null,name:'Nouveau deck',dice:[]};saveDraft();decks();toast('Deck supprimé.')}}else if(a==='play-deck'){if(legal(draft.dice))launch([...draft.dice])}else if(a==='buy-ten')purchasePouches(10);else if(a==='buy'){if(pendingPouches())openNextPouch();else purchasePouches(1)}});
$('export-profile').onclick=()=>{const blob=new Blob([JSON.stringify(profile,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='hackenia-sauvegarde.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};$('import-profile').onclick=()=>$('import-file').click();$('import-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>1000000)throw Error();const p=validate(JSON.parse(await f.text()));if(!confirm('Remplacer la collection, les Bubulles et les decks de ce navigateur par cette sauvegarde ?'))return;if(commit(p)){storageOK=true;recovery=false;draft={id:null,name:'Nouveau deck',dice:[]};saveDraft();render();toast('Sauvegarde importée.')}}catch{toast('Ce fichier n’est pas une sauvegarde valide. Les données actuelles sont conservées.')}finally{e.target.value=''}};
const back=document.createElement('button');back.id='menu-return';back.textContent='← Menu';back.title='Retour au menu';back.setAttribute('aria-label','Retour au menu');back.onclick=()=>navigate('home',true);document.querySelector('.header-actions').prepend(back);window.addEventListener('hashchange',()=>{const h=location.hash.slice(1);if(h==='partie')return;const v=tabs.some(t=>t[0]===h)?h:'home';if(v!==view||!document.body.classList.contains('portal-open'))navigate(v)});window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{profile=validate(JSON.parse(e.newValue));hasSavedProfile=true;updateStartChoices();wallet();if(document.body.classList.contains('portal-open'))render();toast('Collection actualisée depuis un autre onglet.')}catch{toast('Une sauvegarde reçue d’un autre onglet est illisible.')}}});navigate(tabs.some(t=>t[0]===location.hash.slice(1))?location.hash.slice(1):'home');
showStartMenu();
